      A3: "% of cars fed into human driven ride-hail network",
      C3: 0.0,
      D3: 0.0,
      E3: 0.0,
      F3: 0.0,
      G3: 0.0,
      H3: 0.0,
      I3: "=IF(((HumanRideHailMaxShare*(0.5^($L$1-I1)))*EV!I3*RideHailMilesPerCar+H8)>(HumanRideHailMaxMiles),(HumanRideHailMaxMiles-H8)/RideHailMilesPerCar/EV!I3,(HumanRideHailMaxShare*(0.5^($L$1-I1))))",
      J3: "=IF(((HumanRideHailMaxShare*(0.5^($L$1-J1)))*EV!J3*RideHailMilesPerCar+I8)>(HumanRideHailMaxMiles),(HumanRideHailMaxMiles-I8)/RideHailMilesPerCar/EV!J3,(HumanRideHailMaxShare*(0.5^($L$1-J1))))",
      K3: "=IF(((HumanRideHailMaxShare*(0.5^($L$1-K1)))*EV!K3*RideHailMilesPerCar+J8)>(HumanRideHailMaxMiles),(HumanRideHailMaxMiles-J8)/RideHailMilesPerCar/EV!K3,(HumanRideHailMaxShare*(0.5^($L$1-K1))))",
      L3: "=IF(((HumanRideHailMaxShare*(0.5^($L$1-L1)))*EV!L3*RideHailMilesPerCar+K8)>(HumanRideHailMaxMiles),(HumanRideHailMaxMiles-K8)/RideHailMilesPerCar/EV!L3,(HumanRideHailMaxShare*(0.5^($L$1-L1))))",
      N3: "Input. Formula uses max addressable human ride-hail miles to limit this %. We assume at the earliest, human ride hail could start in 2026.",
      A4: "% of ride-hail cars fed into autonomous network",
      G4: "=IF(OR(HumanRideHailMaxShare=0,RobotaxiLaunchDelay>G1-LaunchBaseYear,G3=0),0,IF(MIN((G15-F15)/(G3*EV!G6+F6),MIN(1,G13*4))<F4,MIN(1,G13*4),MIN(MIN(1,G13*4),(G15-F15)/(G3*EV!G6+F6))))",
      H4: "=IF(OR(HumanRideHailMaxShare=0,RobotaxiLaunchDelay>H1-LaunchBaseYear,H3=0),0,IF(MIN((H15-G15)/(H3*EV!H6+G6),MIN(1,H13*4))<G4,MIN(1,H13*4),MIN(MIN(1,H13*4),(H15-G15)/(H3*EV!H6+G6))))",
      I4: "=IF(OR(HumanRideHailMaxShare=0,RobotaxiLaunchDelay>I1-LaunchBaseYear,I3=0),0,IF(MIN((I15-H15)/(I3*EV!I6+H6),MIN(1,I13*4))<H4,MIN(1,I13*4),MIN(MIN(1,I13*4),(I15-H15)/(I3*EV!I6+H6))))",
      J4: "=IF(OR(HumanRideHailMaxShare=0,RobotaxiLaunchDelay>J1-LaunchBaseYear,J3=0),0,IF(MIN((J15-I15)/(J3*EV!J6+I6),MIN(1,J13*4))<I4,MIN(1,J13*4),MIN(MIN(1,J13*4),(J15-I15)/(J3*EV!J6+I6))))",
      K4: "=IF(OR(HumanRideHailMaxShare=0,RobotaxiLaunchDelay>K1-LaunchBaseYear,K3=0),0,IF(MIN((K15-J15)/(K3*EV!K6+J6),MIN(1,K13*4))<J4,MIN(1,K13*4),MIN(MIN(1,K13*4),(K15-J15)/(K3*EV!K6+J6))))",
      L4: "=IF(OR(HumanRideHailMaxShare=0,RobotaxiLaunchDelay>L1-LaunchBaseYear,L3=0),0,IF(MIN((L15-K15)/(L3*EV!L6+K6),MIN(1,L13*4))<K4,MIN(1,L13*4),MIN(MIN(1,L13*4),(L15-K15)/(L3*EV!L6+K6))))",
      N4: "Formula uses autonomous adoption curve to feed ride-hail cars into autonomous network when applicable",
      A5: "Human ride-hail cars added annually (not in millions)",
      C5: "=IF(C3=0,0,ROUND((C3*EV!C3)-(C4*C3*EV!C3+C4*B6),0))",
      D5: "=IF(D3=0,0,ROUND((D3*EV!D3)-(D4*D3*EV!D3+D4*C6),0))",
      E5: "=IF(E3=0,0,ROUND((E3*EV!E3)-(E4*E3*EV!E3+E4*D6),0))",
      F5: "=IF(F3=0,0,ROUND((F3*EV!F3)-(F4*F3*EV!F3+F4*E6),0))",
      G5: "=IF(G3=0,0,ROUND((G3*EV!G3)-(G4*G3*EV!G3+G4*F6),0))",
      H5: "=IF(H3=0,0,ROUND((H3*EV!H3)-(H4*H3*EV!H3+H4*G6),0))",
      I5: "=IF(I3=0,0,ROUND((I3*EV!I3)-(I4*I3*EV!I3+I4*H6),0))",
      J5: "=IF(J3=0,0,ROUND((J3*EV!J3)-(J4*J3*EV!J3+J4*I6),0))",
      K5: "=IF(K3=0,0,ROUND((K3*EV!K3)-(K4*K3*EV!K3+K4*J6),0))",
      L5: "=IF(L3=0,0,ROUND((L3*EV!L3)-(L4*L3*EV!L3+L4*K6),0))",
      N5: "Ridehail cars added to the network minus the ridehail cars that are fed into robotaxis. In some years this could become negative if the # of cars in the ridehail install base that is added to the robotaxi network exceeds the number of new human ridehail cars added that year.",
      A6: "Cumulative human ride-hail cars (not in millions)",
      C6: "=C5",
